import { FC, useId } from "react";

import { IIconProps } from "@/types/icons";

export const MainPageBackgroundPhoto: FC<IIconProps> = ({
  width = 775,
  height = 900,
}) => {
  const uniqueId = useId();
  const patternId = `${uniqueId}-pattern`;
  const imageId = `${uniqueId}-image`;

  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 775 900"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
    >
      <rect
        width="774.252"
        height="1161.58"
        transform="matrix(-1 0 0 1 774.252 -196.788)"
        fill={`url(#${patternId})`}
      />
      <defs>
        <pattern
          id={patternId}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use xlinkHref={`#${imageId}`} transform="scale(0.00051361 0.000342349)" />
        </pattern>
        <image
          id={imageId}
          width="1947"
          height="2921"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
};

export default MainPageBackgroundPhoto;
